  "long_run_neutrality_boundary": [
    {
      "id": "ERQ-ECON-SP-MONETARY-NEUTRALITY-5019",
      "q": "A student says, “If money is neutral, monetary policy can never affect real output.” What is the best correction?",
      "options": [
        "Neutrality is a long-run claim; short-run real effects can occur even if long-run real output returns to a level set by real factors.",
        "Neutrality means money changes only real output and never prices at any horizon, so even temporary short-run changes in prices, spending, or production cannot occur.",
        "Neutrality applies only during recessions, not in long-run comparisons of nominal and real economic variables.",
        "Neutrality means every monetary-policy action has exactly zero effect on prices, output, employment, and interest rates at every horizon."
      ],
      "tag": "monetary_neutrality",
      "type": "application",
      "objective": "31.2",
      "difficulty": "microRepair",
      "primarySkill": "long_run_neutrality_boundary",
      "repairSkill": "long_run_neutrality_boundary",
      "feedback": "Monetary neutrality is a long-run proposition: nominal variables can change while real output and other real variables return to levels determined by real factors.",
      "aHash": "d9a97d35c2bf904440e19fb303762415e061a92d1b2f2e3387f70830947f2d4b",
      "canonicalId": "ECON-SP-MONETARY-NEUTRALITY-5019",
      "primaryConceptId": "monetary-neutrality",
      "secondaryConceptIds": [],
      "instructionalRole": "repair",
      "canonicalDifficulty": "unknown",
      "originalSourcePool": "monetary_neutrality",
      "originalBossTier": null,
      "secondarySkills": [],
      "commonError": "Treats monetary neutrality as a claim that money can never affect real activity.",
      "composerLibrarySha256": "ca58924188abfe6a274244df230dca1128f6af5207512de9f9dd0efc09ece457"
    }
  ],
